def draw_confusion_matrix(total_logits, y_test, y_test_pred, pre, rec, f1, acc, auc, label_name,
                          title="Confusion Matrix", pdf_save_png=None, pdf_save_pdf=None, feature=None, dpi=1600):
    y_test = y_test.cpu().numpy()
    y_test_pred = y_test_pred.cpu().numpy()
    feature = 'OCN'
    # ax[0]
    cm = confusion_matrix(y_true=y_test, y_pred=y_test_pred, normalize='true')
    fig, ax = plt.subplots(1, 2, figsize=(12, 6))
    sns.heatmap(cm, annot=False, cmap='Blues', xticklabels=[], yticklabels=[], ax=ax[0], square=True) # xticklabels=[], yticklabels=[],

    # for i in range(len(label_name)):
    #     value = f"{cm[i, i]:.2f}"
    #     if cm[i, i] > 0.9:
    #         ax[0].text(i + 0.5, i + 0.5, value, verticalalignment='center', horizontalalignment='center', color='black',
    #                    fontsize=12)

    ax[0].set_title(feature + ' Confusion Matrix', fontsize=14, fontweight='bold')
    ax[0].set_yticks(np.arange(len(label_name)) + 0.5, label_name)
    ax[0].set_xticks(np.arange(len(label_name)) + 0.5, label_name, rotation=45, ha='right')
    ax[0].set_xlabel('Predicted Label', fontsize=8)
    ax[0].set_ylabel('True Label', fontsize=8)
    # ax[0].tick_params(axis='both', which='both', length=0)
    cbar = ax[0].collections[0].colorbar
    cbar.set_label('Normalized Count', rotation=270, labelpad=15, fontsize=8)

