    skplt.metrics.plot_roc_curve(y_test, y_score, curves=('micro', 'macro'), ax=ax[1], title=feature + ' ROC Curves',
                                 text_fontsize=10)

    ax[1].text(0.98, 0.15, 'Model: SPT  \n'
                           'Precision: {:.4f}\n'
                           'Recall: {:.4f}\n'
                           'Accuracy: {:.4f}\n'
                           'F1-score: {:.4f}'.format(pre, rec, acc, f1),
               fontsize="medium",
               transform=ax[1].transAxes,
               verticalalignment='bottom',
               horizontalalignment='right', linespacing=1.5,
               bbox=dict(facecolor='none', edgecolor='black', boxstyle='round,pad=0.2', alpha=0.3, linewidth=1, linestyle='-')
               )
    ax[1].axis('square')

    plt.tight_layout()
